const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const seen = [];
  const service = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); } });
  const receipts = await Promise.all(Array.from({ length: 10 }, () => service.pay('a', 'k', 100)));
  assert.ok(receipts.every(r => r === receipts[0]));
  assert.equal(ledger.entries.length, 1);
  await assert.rejects(service.pay('a', 'k', 101), { message: 'key conflict' });
  assert.equal(seen.length, 10);
  await service.pay('b', 'k', 101);
  assert.equal(ledger.entries.length, 2);

  const direct = new Ledger();
  const results = await Promise.allSettled([direct.apply('a', 'k', 1), direct.apply('a', 'k', 2)]);
  assert.equal(results[0].status, 'fulfilled');
  assert.equal(results[1].reason.message, 'key conflict');
  assert.equal(direct.entries.length, 1);

  const retryLedger = new Ledger();
  const forwarded = [];
  const failure = new Transient('last failure');
  const retry = new PaymentService(retryLedger, { acknowledge: async r => {
    forwarded.push(r);
    throw failure;
  } });
  await assert.rejects(retry.pay('a', 'k', 1, 5), e => e === failure);
  assert.equal(forwarded.length, 5);
  assert.ok(forwarded.every(r => r === retryLedger.entries[0]));
  assert.equal(retryLedger.entries.length, 1);
  const success = new PaymentService(retryLedger, { acknowledge: async r => {
    assert.equal(r, forwarded[0]);
  } });
  assert.equal(await success.pay('a', 'k', 1), forwarded[0]);

  let calls = 0;
  const fatal = new Error('fatal');
  const noRetry = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw fatal; } });
  await assert.rejects(noRetry.pay('a', 'k', 1), e => e === fatal);
  assert.equal(calls, 1);

  const invalid = new PaymentService({ apply: async () => { throw new Error('ledger called'); } },
    { acknowledge: async () => { throw new Error('transport called'); } });
  for (const args of [ ['', 'k', 1], ['a', '', 1], [1, 'k', 1], ['a', {}, 1],
    ['a', 'k', 0], ['a', 'k', 1.5], ['a', 'k', NaN], ['a', 'k', Infinity],
    ...[0, 6, 1.5, NaN, Infinity, '3', null].map(n => ['a', 'k', 1, n]) ]) {
    await assert.rejects(invalid.pay(...args), { message: 'invalid payment' });
  }
  await assert.rejects(direct.apply('', 'k', 1), { message: 'invalid payment' });
  assert.equal(direct.entries.length, 1);
}
main().catch(error => { console.error(error); process.exitCode = 1; });
